def get_all_ecf(inpath: Optional[str] = None) -> list:
    """Download all .ecf template files from DEMO_URL into *inpath*.

    Uses the GitHub Git Trees API (one request) to list the full tree,
    then downloads every file whose path ends in '.ecf'.  Files are
    saved flat into *inpath* (subdirectory structure is discarded).

    :param inpath: str or None, destination directory (created if absent).
                   If None an OS-independent temporary directory is created.
    :return: list of str, absolute paths of every file written
    """
    import requests

    # deal with no path given -> OS-independent temporary directory
    if inpath is None:
        inpath = tempfile.mkdtemp(prefix='pogos_ecf_')
    # ensure the output directory exists
    os.makedirs(inpath, exist_ok=True)

    # parse DEMO_URL → repo coordinates
    owner, repo, branch, base_path = _parse_github_url(DEMO_URL)

    # single recursive tree listing
    api_url = (f'https://api.github.com/repos/{owner}/{repo}'
               f'/git/trees/{branch}?recursive=1')
    resp = requests.get(api_url)
    resp.raise_for_status()
    tree = resp.json().get('tree', [])

    downloaded = []
    # Loop around the tree and only download .ecf files
    for item in tree:
        item_path = item.get('path', '')
        if (item.get('type') == 'blob'
                and item_path.startswith(base_path)
                and item_path.endswith('.ecf')):
            filename = os.path.basename(item_path)
            raw_url = (f'https://raw.githubusercontent.com'
                       f'/{owner}/{repo}/{branch}/{item_path}')
            r = requests.get(raw_url)
            r.raise_for_status()
            outfile = os.path.join(inpath, filename)
            with open(outfile, 'w') as fh:
                fh.write(r.text)
            downloaded.append(outfile)

    return downloaded


def interpret_ecf(filename: str) -> ConstDict:
    """Read a Eureka! ECF file and return a populated ConstantsDict.

    Each data line ``name   value  # comment`` becomes a Const with:
      - ``name``  : first whitespace-delimited token
      - ``value`` : second token, typed (bool/int/float/list/str/path)
      - ``dtype`` : inferred from the value
      - ``description``: inline comment text (continuation comment lines are
                         appended)
      - ``options``: extracted when the comment contains "Options are '...'"
      - ``group`` : the most recent section-header comment (after the first
                   data variable has been seen)
    """
    cdict = ConstDict(filename)
    seen_groups = set()

    for rec in _parse_ecf_records(filename):
        section = rec['section']
        # convert section header text -> group key (None if no section)
        group_key = _ecf_group_name(section) if section else None
        # register the group once (keep the raw header text as description)
        if group_key is not None and group_key not in seen_groups:
            cdict.add_group(group_key, description=section)
            seen_groups.add(group_key)
        # add the constant
        cdict.add(rec['name'], value=rec['value'], dtype=rec['dtype'],
                  description=rec['description'], options=rec['options'],
                  source=filename, group=group_key, user=True, active=True)

    return cdict


def update_constants_from_ecfs(inpath: Optional[str] = None,
                               redownload: bool = True) -> str:
    """Regenerate the ECF constants block inside ``eureka_constants.py``.

    Workflow:
      1. download (or re-download) the default ecf files from DEMO_URL
      2. for each stage, interpret + merge its flavour ecf files
         (intersection: a parameter is kept only if every flavour defines it;
          its value is the common value if all flavours agree, else None)
      3. write the merged constants as ``Eureka_CDict.add(...)`` calls into a
         marker-delimited, auto-generated block in ``eureka_constants.py``

    Re-running replaces the block in place, so new/changed/removed Eureka
    parameters are picked up automatically.  To override a default value,
    add ``Eureka_CDict.set('<Stage>.<name>', value=...)`` *after* the block;
    such overrides survive regeneration.

    :param inpath: str or None, directory for the ecf files (temp dir if None)
    :param redownload: bool, if True (re)download the ecf files into inpath
    :return: str, path to the modified eureka_constants.py
    """
    # ------------------------------------------------------------------
    # 1. obtain the ecf files
    # ------------------------------------------------------------------
    if inpath is None:
        inpath = tempfile.mkdtemp(prefix='pogos_ecf_')
    if redownload:
        get_all_ecf(inpath)

    # ------------------------------------------------------------------
    # 2. merge ecf files per stage (intersection)
    # ------------------------------------------------------------------
    stage_config = [(1, 'STAGE1', S1_ECFS),
                    (2, 'STAGE2', S2_ECFS),
                    (3, 'STAGE3', S3_ECFS),
                    (4, 'STAGE4', S4_ECFS),
                    (5, 'STAGE5', S5_ECFS),
                    (6, 'STAGE6', S6_ECFS)]
    stage_records: "OrderedDict[str, List[dict]]" = OrderedDict()
    for stage_num, cgroup_name, flavours in stage_config:
        files = _find_stage_files(inpath, stage_num, flavours)
        stage_records[cgroup_name] = _merge_ecf_stage(files)

    # ------------------------------------------------------------------
    # 3. generate + write the auto block
    # ------------------------------------------------------------------
    block_lines = _generate_constant_block(stage_records)
    target_path = os.path.join(os.path.dirname(__file__), TARGET_CONST_FILE)
    _write_block_to_target(target_path, block_lines)
    return target_path


def write_ecf_from_cdict(cdict: ConstDict, cgroup: str, filename: str) -> str:
    """Write an ecf file from the constants of ``cgroup`` in ``cdict``.

    This is the inverse of :func:`interpret_ecf` / merging: it takes the POGOS
    constants for a given stage group and serialises them back to Eureka's ecf
    ``name   value   # description`` format, ready to hand to Eureka.

    :param cdict: ConstantsDict, the populated constants dictionary
    :param cgroup: str, the stage group to export (e.g. 'Stage 1')
    :param filename: str, output ecf file path
    :return: str, the output filename
    """
    lines = []
    for key in cdict.storage:
        const = cdict.storage[key]
        # only export Const instances belonging to the requested group
        if not isinstance(const, Const):
            continue
        if const.group != cgroup:
            continue
        value_str = _format_ecf_value(const.value, const.dtype)
        if const.description:
            lines.append('{0:<24s} {1}  # {2}'.format(const.name, value_str,
                                                       const.description))
        else:
            lines.append('{0:<24s} {1}'.format(const.name, value_str))
    # write the file
    with open(filename, 'w') as fh:
        fh.write('\n'.join(lines) + '\n')
    return filename


def ecf_from_params(params: ParamDict, stage=int):
    """

    :param params:
    :param stage:
    :return:
    """
    # get ecf path
    ecf_path = str(params['EUREKA.PATHS.ECF_PATH'])
    # get the event label
    eventlabel = str(params['EUREKA.GENERAL.EVENTLABEL'])
    # set filename
    ecf_filename = f'S{stage}_{eventlabel}.ecf'
    # construct absolute path
    abs_ecf_path = os.path.join(ecf_path, ecf_filename)
    # storage for writing
    lines = []
    # loop around parameters (assume it is the correct sub-dictionary
    for key in params:
        # get instance (cdict entry)
        const = params.instances[key]
        # deal with missing instance
        if const is None:
            continue
        # format value string
        value_str = _format_ecf_value(const.value, const.dtype)
        # construct a description (if description given)
        if const.description:
            lines.append('{0:<24s} {1}  # {2}'.format(const.name, value_str,
                                                      const.description))
        else:
            lines.append('{0:<24s} {1}'.format(const.name, value_str))
    # write the file
    with open(abs_ecf_path, 'w') as ecf_file:
        ecf_file.write('\n'.join(lines) + '\n')
    return abs_ecf_path


