# =============================================================================
def _parse_github_url(url: str):
    """Parse a GitHub tree URL into (owner, repo, branch, path).

    Expects: https://github.com/{owner}/{repo}/tree/{branch}/{path}
    """
    import requests as _requests  # noqa: F401 – checked at call site
    stripped = url.replace('https://github.com/', '')
    parts = stripped.split('/')
    owner = parts[0]
    repo = parts[1]
    # parts[2] == 'tree'
    branch = parts[3]
    path = '/'.join(parts[4:])
    return owner, repo, branch, path


def _parse_ecf_records(filename: str) -> List[Dict[str, Any]]:
    """Parse an ecf file into a flat list of parameter records.

    Each record is a dict with keys: name, value, dtype, description, options,
    section.  Section-header comments (a '#' in column 0, after the first data
    line) update the running ``section``; indented comment lines ('#' preceded
    by whitespace) are treated as continuations of the previous parameter's
    description.  File-header comments (before the first data line) and lines
    containing a URL are ignored for sectioning.

    :param filename: str, path to the ecf file
    :return: list of record dicts
    """
    with open(filename, 'r') as fh:
        lines = fh.readlines()

    records: List[Dict[str, Any]] = []
    section = None
    seen_data = False

    for raw in lines:
        line = raw.rstrip()
        # skip blank lines
        if not line.strip():
            continue
        # comment-only line
        if line.lstrip().startswith('#'):
            text = line.strip().lstrip('#').strip()
            # indented comment -> continuation of previous description
            if line[0] in (' ', '\t') and records and text:
                prev = records[-1]
                if prev['description']:
                    prev['description'] += ' ' + text
                else:
                    prev['description'] = text
                # options may now be derivable from the fuller description
                if prev['options'] is None:
                    prev['options'] = _parse_ecf_options(prev['description'],
                                                         prev.get('dtype'))
            # column-0 comment after data -> section header
            elif seen_data and text and 'http' not in text:
                section = text
            continue
        # data line
        seen_data = True
        parts = line.split(None, 1)
        if len(parts) < 2:
            continue
        name = parts[0].strip()
        rest = parts[1].strip()
        # split off inline comment
        if '#' in rest:
            value_str, comment_str = rest.split('#', 1)
            value_str = value_str.strip()
            description = comment_str.strip() or None
        else:
            value_str = rest.strip()
            description = None
        value, dtype, description = _parse_ecf_value(value_str, description)
        options = _parse_ecf_options(description, dtype)
        records.append(dict(name=name, value=value, dtype=dtype,
                            description=description, options=options,
                            section=section))
    return records


def _ecf_group_name(text: str) -> str:
    """Convert a section-header comment to an uppercase group key."""
    return re.sub(r'[^A-Z0-9]+', '_', text.upper()).strip('_')


def _parse_ecf_value(value_str: str, description: str = None
                     ) -> Tuple[Any, Optional[Union[Type, str]], Optional[str]]:
    """Parse a raw ECF value string, returning (value, dtype)."""
    # file path (not a valid python literal, handle explicitly)
    if value_str.startswith('/'):
        if description is None:
            description = f'E.g. {value_str}'
        else:
            description += f' E.g {value_str}'

        return None, 'path', description
    # explicit None spellings
    if value_str in ('None', 'null', 'NONE'):
        return None, None, description
    # try to interpret as a python literal
    #   handles: quoted strings, ints, floats, bools, lists, tuples
    try:
        value = ast.literal_eval(value_str)
    except (ValueError, SyntaxError):
        # unquoted bareword string (e.g. uncal, median, percentile)
        # Eureka sometimes wraps comma-separated string values in brackets
        # (e.g. [dynesty] or [batman_tr,polynomial]) even though the intended
        # value is still a plain string. Normalize those here so generated
        # constants do not keep the literal brackets.
        stripped = value_str.strip()
        if (stripped.startswith('[') and stripped.endswith(']') and
                stripped.count('[') == 1 and stripped.count(']') == 1):
            inner = stripped[1:-1].strip()
            if inner:
                return inner, str, description
        return value_str, str, description
    # map python type -> dtype (bool must precede int)
    if isinstance(value, bool):
        return value, bool, description
    if isinstance(value, int):
        return value, int, description
    if isinstance(value, float):
        return value, float, description
    if isinstance(value, (list, tuple)):
        return list(value), list, description
    if isinstance(value, str):
        return value, str, description
    if value is None:
        return None, None, description
    # fallback: plain string
    return value_str, str, description


def _parse_ecf_options(description: Optional[str],
                       dtype: Optional[Union[Type, str]] = None
                       ) -> Optional[list]:
    """Extract an options list from a comment.

    Handles the various (inconsistent) Eureka spellings, e.g.::

        # Options are 'none', 'quarter', 'half', 'all'
        # Options: [percentile, min, defined]
        # Options: std (Standard Deviation), median (...), mean (...)

    Returns a clean list of bareword tokens, or None if no options found.
    """
    if description is None:
        return None
    low = description.lower()
    # locate the start of the options listing
    if 'options are' in low:
        marker = low.index('options are') + len('options are')
    elif 'options:' in low:
        marker = low.index('options:') + len('options:')
    elif 'options' in low and '[' in description:
        marker = low.index('options') + len('options')
    else:
        return None
    # the text following the marker, stripped of wrapping punctuation
    tail = description[marker:].strip().strip(':').strip().strip('[](){}')

    # Expand integer ranges such as "1-5" or "1 to 5" when present.
    range_tokens = []
    for start_str, end_str in re.findall(r'(?<!\d)(\d+)\s*(?:-|to)\s*(\d+)',
                                         tail, flags=re.IGNORECASE):
        start_i = int(start_str)
        end_i = int(end_str)
        step = 1 if end_i >= start_i else -1
        range_tokens.extend([str(v) for v in range(start_i, end_i + step, step)])

    # Also parse explicit comma/semicolon-separated option items.
    # Keep only the leading token from each item (as before), but allow
    # compact lists like "1,2,3,4,5" and per-item range expressions.
    literal_tokens = []
    for part in re.split(r'[,;]', tail):
        cleaned = part.strip().strip("'\"[](){}")
        if not cleaned:
            continue
        range_match = re.match(r'^(\d+)\s*(?:-|to)\s*(\d+)', cleaned,
                               flags=re.IGNORECASE)
        if range_match:
            start_i = int(range_match.group(1))
            end_i = int(range_match.group(2))
            step = 1 if end_i >= start_i else -1
            literal_tokens.extend(
                [str(v) for v in range(start_i, end_i + step, step)]
            )
            continue
        token = re.split(r'[\s(]', cleaned, 1)[0].strip("'\"")
        if token and re.match(r'^[A-Za-z0-9_.+-]+$', token):
            literal_tokens.append(token)

    # preserve order, deduplicate
    opts = []
    for token in range_tokens + literal_tokens:
        if token not in opts:
            opts.append(token)
    if not opts:
        return None

    # If a dtype was provided, attempt to convert the option tokens to that
    # dtype. If conversion for an individual token fails, fall back to the
    # original string token to preserve information.
    def _convert_token(tok: str):
        # handle None-like tokens
        if tok.lower() in ("none", "null", "nil"):
            return None
        # dtype may be a string name (e.g. 'path') or an actual type object
        target = dtype
        if isinstance(dtype, str):
            name = dtype.lower()
            if name == 'int':
                target = int
            elif name == 'float':
                target = float
            elif name in ('str', 'string', 'path'):
                target = str
            elif name in ('bool', 'boolean'):
                target = bool
            else:
                # unknown string dtype -> do not convert
                target = None
        # perform conversion based on target type
        if target is int:
            try:
                return int(tok)
            except Exception:
                return tok
        if target is float:
            try:
                return float(tok)
            except Exception:
                return tok
        if target is bool:
            tl = tok.lower()
            if tl in ('true', 't', 'yes', 'y', '1'):
                return True
            if tl in ('false', 'f', 'no', 'n', '0'):
                return False
            return tok
        if target is list:
            # try literal eval (e.g. '[1,2]')
            try:
                val = ast.literal_eval(tok)
                return list(val) if isinstance(val, (list, tuple)) else tok
            except Exception:
                return tok
        if target is None or target is str:
            return tok
        # fallback: try literal_eval for numeric-like tokens
        try:
            return ast.literal_eval(tok)
        except Exception:
            return tok

    converted = [_convert_token(t) for t in opts]
    return converted or None


def _find_stage_files(directory: str, stage: int,
                      flavours: List[str]) -> List[str]:
    """Find the downloaded ecf files for a stage's flavours.

    Filenames follow ``S{stage}_{flavour}.ecf`` but flavour spelling is not
    always exact, so we try a couple of explicit candidates then fall back to
    a substring match.

    :param directory: str, directory containing the downloaded ecf files
    :param stage: int, the stage number (1, 2 or 3)
    :param flavours: list of str, the flavour stems for this stage
    :return: list of str, matched file paths (one per flavour found)
    """
    available = [f for f in os.listdir(directory) if f.endswith('.ecf')]
    prefix = 'S{0}'.format(stage)
    found = []
    for flavour in flavours:
        match = None
        # explicit candidates
        candidates = ['{0}_{1}.ecf'.format(prefix, flavour),
                      '{0}_{1}_template.ecf'.format(prefix, flavour)]
        for cand in candidates:
            if cand in available:
                match = cand
                break
        # substring fallback (e.g. flavour 'niriss_soss')
        if match is None:
            for fname in available:
                if (fname.startswith(prefix + '_') and flavour in fname):
                    match = fname
                    break
        if match is not None:
            found.append(os.path.join(directory, match))
    return found


def _merge_ecf_stage(files: List[str]) -> List[Dict[str, Any]]:
    """Merge the parameters of several ecf files (intersection).

    A parameter is kept only if it is present in *every* file.  Its value is
    the shared value when all files agree, otherwise None (so a user can set
    an explicit default later).

    :param files: list of str, ecf file paths for a single stage
    :return: list of merged record dicts (name, value, dtype, description,
             options) in first-seen order
    """
    if not files:
        return []
    nfiles = len(files)
    # ordered accumulation of per-name info
    acc: "OrderedDict[str, Dict[str, Any]]" = OrderedDict()
    for fpath in files:
        for rec in _parse_ecf_records(fpath):
            name = rec['name']
            if name not in acc:
                acc[name] = dict(name=name, count=0, values=[],
                                 dtype=rec['dtype'],
                                 description=rec['description'],
                                 options=rec['options'])
            info = acc[name]
            info['count'] += 1
            info['values'].append(rec['value'])
            # backfill metadata from whichever file first provides it
            if info['dtype'] is None and rec['dtype'] is not None:
                info['dtype'] = rec['dtype']
            if info['description'] is None and rec['description']:
                info['description'] = rec['description']
            if info['options'] is None and rec['options']:
                info['options'] = rec['options']
    # keep only the intersection and resolve values
    merged = []
    for name, info in acc.items():
        # intersection: must appear in every file
        if info['count'] != nfiles:
            continue
        # agreement check
        unique = []
        for val in info['values']:
            if val not in unique:
                unique.append(val)
        value = unique[0] if len(unique) == 1 else None
        merged.append(dict(name=name, value=value, dtype=info['dtype'],
                           description=info['description'],
                           options=info['options']))
    return merged


def _format_dtype(dtype: Optional[Union[Type, str]]) -> str:
    """Format a dtype as a python source snippet."""
    if dtype is None:
        return 'None'
    if isinstance(dtype, str):
        return repr(dtype)
    return dtype.__name__


def _format_add_call(rec: Dict[str, Any]) -> List[str]:
    """Format one merged record as Eureka_CDict.add(...) source lines.

    Lines are kept within MAX_LINE characters: kwargs are greedily packed
    onto each line, and the (often long) description string is wrapped as
    a sequence of concatenated string literals when needed.
    """
    head = '{0}.add('.format(TARGET_CDICT)
    indent = ' ' * len(head)
    # everything except description
    scalars = [
        repr(rec['name']),
        'value={0!r}'.format(rec['value']),
        'dtype={0}'.format(_format_dtype(rec['dtype'])),
        'options={0!r}'.format(rec['options']),
        'source=__NAME__',
        'user={0}'.format(rec.get('user', True)),
        'active={0}'.format(rec.get('active', True)),
    ]
    # set not_none when requested via NOT_NONE_OVERRIDE
    if rec.get('not_none'):
        scalars.append('not_none=True')
    scalars.append('group=cgroup')
    # greedy pack scalar fragments onto lines (account for trailing ',')
    lines: List[str] = []
    current = head + scalars[0]
    for frag in scalars[1:]:
        candidate = current + ', ' + frag
        if len(candidate) + 1 <= MAX_LINE:
            current = candidate
        else:
            lines.append(current + ',')
            current = indent + frag
    # tack on description (inline if it fits, else on its own / wrapped)
    desc = rec['description']
    desc_repr = repr(desc) if desc is not None else 'None'
    inline = ', description={0})'.format(desc_repr)
    if len(current) + len(inline) <= MAX_LINE:
        lines.append(current + inline)
    else:
        lines.append(current + ',')
        own_line = indent + 'description=' + desc_repr + ')'
        if desc is None or len(own_line) <= MAX_LINE:
            lines.append(own_line)
        else:
            lines.extend(_wrap_description_kwarg(desc, indent))
    return lines


def _wrap_description_kwarg(desc: str, indent: str) -> List[str]:
    """Wrap a long description across multiple concatenated string literals.

    Produces lines like::

        <indent>description=('first chunk '
                             'second chunk '
                             'last chunk')
    """
    open_line = indent + 'description=('
    cont_indent = ' ' * len(open_line)
    # budget the chunk text width so repr(chunk)+space+'))' still fits.
    # We re-attach a trailing space to every non-final chunk so the implicit
    # string concatenation preserves word boundaries.
    text_width = max(10, MAX_LINE - len(cont_indent) - 4)
    while text_width >= 5:
        chunks = textwrap.wrap(desc, width=text_width,
                               break_long_words=False,
                               break_on_hyphens=False) or [desc]
        # restore inter-chunk spaces (textwrap.wrap strips them)
        chunks = [c + ' ' if i < len(chunks) - 1 else c
                  for i, c in enumerate(chunks)]
        out = []
        for i, ch in enumerate(chunks):
            line = (open_line if i == 0 else cont_indent) + repr(ch)
            if i == len(chunks) - 1:
                line += '))'  # close the implicit-concat group AND .add(
            out.append(line)
        if all(len(line) <= MAX_LINE for line in out):
            return out
        text_width -= 2
    return out


def _generate_constant_block(
        stage_records: "OrderedDict[str, List[dict]]") -> List[str]:
    """Build the full auto-generated block (marker to marker) as text lines."""
    lines = [BEGIN_MARKER,
             '# Regenerated by '
             'eureka_ecf.update_constants_from_ecfs() - do not hand-edit.',
             '# Override values AFTER this block with '
             '{0}.set(...).'.format(TARGET_CDICT)]
    for cgroup_name, records in stage_records.items():
        lines.append('')
        lines.append('cgroup = {0!r}'.format(cgroup_name))
        for rec in records:
            rec_out = dict(rec)
            stage_overrides = OPTION_OVERRIDES.get(cgroup_name, {})
            if rec_out['name'] in stage_overrides:
                override = stage_overrides[rec_out['name']]
                rec_out['options'] = override
            # override the value from DEFAULT_VALUES (replaces the ecf value)
            stage_defaults = DEFAULT_VALUES.get(cgroup_name, {})
            if rec_out['name'] in stage_defaults:
                rec_out['value'] = stage_defaults[rec_out['name']]
            # mark not_none parameters for this stage
            notnone_names = NOT_NONE_OVERRIDE.get(cgroup_name, [])
            rec_out['not_none'] = rec_out['name'] in notnone_names
            # override active/user flags for this stage (default True)
            stage_active = ACTIVE_OVERRIDE.get(cgroup_name, {})
            rec_out['active'] = stage_active.get(rec_out['name'], True)
            stage_user = USER_OVERRIDE.get(cgroup_name, {})
            rec_out['user'] = stage_user.get(rec_out['name'], True)
            lines.extend(_format_add_call(rec_out))
    lines.append(END_MARKER)
    return lines


def _write_block_to_target(target_path: str, block_lines: List[str]):
    """Insert or replace the auto-generated block in the target file."""
    with open(target_path, 'r') as fh:
        content = fh.read()
    block = '\n'.join(block_lines)
    # replace existing block if markers present
    if BEGIN_MARKER in content and END_MARKER in content:
        start = content.index(BEGIN_MARKER)
        end = content.index(END_MARKER) + len(END_MARKER)
        new_content = content[:start] + block + content[end:]
    else:
        # insert before the "Start of code" divider
        anchor = ('# ====================================================='
                  '========================\n# Start of code')
        idx = content.find(anchor)
        if idx == -1:
            new_content = content.rstrip('\n') + '\n\n\n' + block + '\n'
        else:
            new_content = content[:idx] + block + '\n\n\n' + content[idx:]
    with open(target_path, 'w') as fh:
        fh.write(new_content)


def _format_ecf_value(value: Any, dtype: Optional[Union[Type, str]]) -> str:
    """Format a constant value back into ecf textual form."""
    if value is None:
        return 'None'
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (list, tuple)):
        return str(list(value))
    if dtype == 'path':
        return str(value)
    # strings (and everything else) are written verbatim
    return str(value)


